'use strict';
// Home Screen design study. Native WidgetKit/AppWidget integration is deferred.
const widgetPreview={mode:'next'};
function widgetNearestEvent(events,mode){if(mode==='quiet')return null;return [...events].filter(r=>r.renewal&&(mode==='next'||(mode==='trial'?r.trial:!r.trial))).sort((a,b)=>a.renewal.localeCompare(b.renewal)||String(a.id).localeCompare(String(b.id)))[0]||null;}
function widgetEventCopy(record,today){if(!record)return {title:'A little peace of mind.',timing:'Nothing coming up',amount:'All clear',type:'quiet'};const days=Math.round((Date.parse(record.renewal+'T00:00:00Z')-Date.parse(today+'T00:00:00Z'))/86400000),verb=record.trial?'Trial ends':'Renews';return {title:record.name,timing:verb+(days===0?' today':days===1?' tomorrow':' in '+days+' days'),amount:record.expectedCharge===false?'Auto-renew off':Number.isFinite(Number(record.price))&&record.price!==null&&record.price!==''?record.currency+' '+Number(record.price).toFixed(2):'Amount not set',type:record.trial?'trial':days===0?'today':'renewal'};}
function widgetDoorScene(){return `<div class="wk-knock-scene" aria-hidden="true"><div class="wk-knock-avatar">${mascotView({expression:'happy',size:92,artworkScale:1.4,halo:false})}<svg class="wk-fist" viewBox="0 0 42 34"><path d="M8 24 7 13q0-5 4-5 3 0 4 4V6q0-4 4-4t4 4v5-4q0-4 4-4t4 4v5q1-4 4-3t3 5v8q0 8-11 9H16q-6-1-8-7Z"/><path d="M15 12v8m8-9v8m8-7v7"/></svg></div><div class="wk-door-frame"><div class="wk-door"><i></i><b></b></div></div><span class="wk-knock-lines"><i></i><i></i><i></i></span><span class="wk-knock-words">knock, knock.</span></div>`;}
function widgetTile(record,size){const copy=widgetEventCopy(record,calendarToday),quiet=!record;return `<button class="wk-tile wk-${size} wk-type-${copy.type} ${quiet?'wk-quiet':''}" data-widget-open="${record?escape(record.id):''}" aria-label="${record?escape(copy.title+'. '+copy.timing+'. '+copy.amount+'. Open subscription'):'Open Renewless'}"><span class="wk-brand"><img src="assets/renewless-mark.svg" alt=""><span>RENEWLESS</span><span class="wk-event-dot"></span></span><span class="wk-final-content">${quiet?`<span class="wk-quiet-art">${mascotView({expression:'happy',size:size==='small'?64:92,artworkScale:1.05,halo:false})}</span><strong class="wk-service">All clear.</strong><span class="wk-timing">Nothing coming up.</span><span class="wk-date-label">A little peace of mind.</span>`:`<span class="wk-event-eyebrow">${record.trial?'TRIAL ENDING':copy.type==='today'?'DUE TODAY':'NEXT RENEWAL'}</span><span class="wk-service"><span class="wk-platform-logo">${platformLogo(record.name)}</span>${escape(record.name)}</span><strong class="wk-amount ${copy.amount.length>12?'wk-amount-compact':''}">${escape(copy.amount)}</strong><span class="wk-timing">${escape(copy.timing)}</span><span class="wk-date-label">${detailDate(record.renewal)}${record.trial&&record.expectedCharge!==false?' · After trial':''}${record.estimated?' · Estimated date':''}</span>${size==='medium'?`<span class="wk-rest-avatar">${mascotView({expression:record.trial?'neutral':'happy',size:96,artworkScale:1,halo:false})}<span>${record.trial?'A little heads-up.':'I’ve got your back.'}</span></span>`:''}`}</span>${quiet?'':widgetDoorScene()}</button>`;}
const widgetDecorativeIcons=[['Renewless','brand'],['Mail','mail'],['Photos','flower'],['Camera','camera'],['Clock','clock'],['Notes','notes'],['Music','music'],['Settings','settings']];
function widgetHomeScreen(){const event=widgetNearestEvent(nearestEvents(),widgetPreview.mode),date=new Date(calendarToday+'T12:00:00Z'),weekday=date.toLocaleDateString('en-US',{weekday:'long',timeZone:'UTC'}),day=date.getUTCDate();return `<div class="widget-home-preview"><div class="wk-home-date">${weekday}, ${date.toLocaleDateString('en-GB',{day:'numeric',month:'long',timeZone:'UTC'})}</div><div class="wk-small-grid"><div>${widgetTile(event,'small')}<span class="wk-app-caption">Renewless</span></div><div><button class="wk-system-calendar" data-go="Calendar" aria-label="Open calendar"><span>${weekday.toUpperCase()}</span><strong>${day}</strong><small>Your day,<br>a little clearer.</small></button><span class="wk-app-caption">Calendar</span></div></div><div class="wk-medium-wrap">${widgetTile(event,'medium')}<span class="wk-app-caption">Renewless</span></div><div class="wk-app-grid" aria-hidden="true">${widgetDecorativeIcons.map(([name,icon])=>`<div><span class="wk-app-icon wk-icon-${icon}">${icon==='brand'?'<img src="assets/renewless-mark.svg" alt="">':widgetAppGlyph(icon)}</span><small>${name}</small></div>`).join('')}</div><div class="wk-home-spacer"></div><div class="wk-page-dots" aria-hidden="true"><i></i><i></i><i></i></div><div class="wk-home-dock" aria-hidden="true">${['phone','compass','message','music'].map(icon=>`<span class="wk-app-icon wk-icon-${icon}">${widgetAppGlyph(icon)}</span>`).join('')}</div></div>`;}
function widgetAppGlyph(type){const paths={mail:'<rect x="4" y="6" width="24" height="20" rx="4"/><path d="m5 8 11 9L27 8"/>',camera:'<path d="m10 8 2-3h8l2 3h4a3 3 0 0 1 3 3v14H3V11a3 3 0 0 1 3-3Z"/><circle cx="16" cy="17" r="6"/>',clock:'<circle cx="16" cy="16" r="12"/><path d="M16 8v9l6 3"/>',notes:'<rect x="6" y="3" width="20" height="26" rx="3"/><path d="M10 10h12M10 16h12M10 22h8"/>',music:'<path d="M12 23V7l15-3v16M12 12l15-3"/><ellipse cx="8" cy="24" rx="4" ry="3"/><ellipse cx="23" cy="21" rx="4" ry="3"/>',settings:'<circle cx="16" cy="16" r="10"/><circle cx="16" cy="16" r="4"/><path d="M16 2v4m0 20v4M2 16h4m20 0h4M6 6l3 3m14 14 3 3M26 6l-3 3M9 23l-3 3"/>',flower:'<path d="M16 16C0-8 32-8 16 16c24-16 24 16 0 0 16 24-16 24 0 0-24 16-24-16 0 0Z"/>',phone:'<path d="M7 4h5l2 7-4 3q3 6 8 8l3-4 7 2v5q-1 5-7 3C10 25 3 16 3 8q0-4 4-4Z"/>',compass:'<circle cx="16" cy="16" r="12"/><path d="m22 10-4 9-8 3 4-9Z"/>',message:'<path d="M28 15q0 12-15 10l-8 4 2-8Q0 9 9 5q19-6 19 10Z"/>'};return `<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[type]||paths.clock}</svg>`;}
function widgetPreviewAfterRender(){document.getElementById('widget-preview-controls')?.remove();if(current!=='Widgets')return;document.getElementById('context').textContent='Final Widgets · approved and locked Small/Medium layouts, event/trial/quiet states and knock motion. Fictional wallpaper/calendar; subscription snapshots follow the shared schedule. Browser motion is a concept, not a native widget installation.';document.querySelector('[data-variant=upgraded] .variant-title h2').textContent='Final';document.querySelector('[data-variant=upgraded] .variant-title small').textContent='Final design · locked';document.querySelector('.footnote').innerHTML='Preview the short knock → reveal, then tap a Renewless widget to open its subscription. iPhone widgets animate supported data updates for up to 2 seconds; no continuous loop or guaranteed animation whenever Home Screen opens. <a href="https://developer.apple.com/documentation/widgetkit/animating-data-updates-in-widgets-and-live-activities" target="_blank" rel="noopener noreferrer">Apple WidgetKit guidance</a>.';document.getElementById('context').insertAdjacentHTML('afterend',`<div class="widget-preview-controls" id="widget-preview-controls" aria-label="Widget inspection controls"><span>PREVIEW</span>${[['next','Next event'],['trial','Trial ending'],['quiet','All clear']].map(([mode,label])=>`<button data-widget-mode="${mode}" aria-pressed="${widgetPreview.mode===mode}">${label}</button>`).join('')}<button data-widget-replay>↻ Replay knock</button></div>`);}
document.addEventListener('click',e=>{const mode=e.target.closest('[data-widget-mode]'),replay=e.target.closest('[data-widget-replay]'),tile=e.target.closest('[data-widget-open]');if(mode){widgetPreview.mode=mode.dataset.widgetMode;render();}else if(replay){render();}else if(tile){const record=allTrackedRecords().find(r=>r.id===tile.dataset.widgetOpen);if(record)openCalendarRecord(record);else go('Home');}});
